const SHOP_TZ = $now.zoneName;
const webhookData = $('Book Appointment Webhook').first().json.body;
const requestedTime = new Date(webhookData.startTime);
const appointmentDuration = $('Set Appointment Configuration').first().json.appointmentDuration || 60;
const workingHoursStart = $('Set Appointment Configuration').first().json.workingHoursStart || 9;
const workingHoursEnd = $('Set Appointment Configuration').first().json.workingHoursEnd || 17;
const searchRangeDays = $('Set Appointment Configuration').first().json.searchRangeDays || 10;
const events = $input.all().map(item => item.json);
const nowJs = new Date();
function isSlotAvailable(startTime, durationMinutes) {
  const endTime = new Date(startTime.getTime() + durationMinutes * 60000);
  for (const event of events) {
    const eventStart = new Date(event.start.dateTime || event.start.date);
    const eventEnd = new Date(event.end.dateTime || event.end.date);
    if (startTime < eventEnd && endTime > eventStart) return false;
  }
  return true;
}
const availableSlots = [];
const reqDT = DateTime.fromISO(webhookData.startTime, { zone: SHOP_TZ });
const startDay = reqDT.startOf('day');
for (let day = 0; day < searchRangeDays; day++) {
  const d = startDay.plus({ days: day });
  if (d.weekday === 6 || d.weekday === 7) continue;
  for (let m = workingHoursStart * 60; m + appointmentDuration <= workingHoursEnd * 60; m += 30) {
    const hour = Math.floor(m / 60), minute = m % 60;
    const slotDT = d.set({ hour, minute, second: 0, millisecond: 0 });
    const slotTime = slotDT.toJSDate();
    if (slotTime < nowJs) continue;
    if (isSlotAvailable(slotTime, appointmentDuration)) {
      const endTime = new Date(slotTime.getTime() + appointmentDuration * 60000);
      const timeDifference = Math.abs(slotTime.getTime() - requestedTime.getTime()) / 60000;
      const isSameDay = slotDT.hasSame(reqDT, 'day');
      availableSlots.push({ startTime: slotTime.toISOString(), endTime: endTime.toISOString(), formatted: slotDT.toFormat("cccc, LLLL d 'at' h:mm a"), timeDifference, isSameDay });
    }
  }
}
availableSlots.sort((a, b) => {
  if (a.isSameDay && !b.isSameDay) return -1;
  if (!a.isSameDay && b.isSameDay) return 1;
  return a.timeDifference - b.timeDifference;
});
const suggestedTimes = availableSlots.slice(0, 3).map(slot => ({ startTime: slot.startTime, endTime: slot.endTime, formatted: slot.formatted }));
return { json: { suggestedTimes, requestedTime: requestedTime.toISOString(), totalSlotsFound: availableSlots.length, searchedDays: searchRangeDays, appointmentDuration } };

const SHOP_TZ = $now.zoneName;
const config = $('Set Reschedule Configuration').first().json;
const requestedStartTime = new Date(config.requestedStartTime);
const dateRangeStart = new Date(config.dateRangeStart);
const dateRangeEnd = new Date(config.dateRangeEnd);
const slotDuration = 60;
const workStart = 9, workEnd = 17, stepMin = 30;
const nowJs = new Date();
const bookedEvents = $input.all().map(item => ({ start: new Date(item.json.start.dateTime || item.json.start.date), end: new Date(item.json.end.dateTime || item.json.end.date) }));
function isSlotAvailable(slotStart, slotEnd) {
  return !bookedEvents.some(ev => slotStart < ev.end && slotEnd > ev.start);
}
const availableSlots = [];
const startDay = DateTime.fromISO(config.dateRangeStart, { zone: SHOP_TZ }).startOf('day');
const endLimit = DateTime.fromISO(config.dateRangeEnd, { zone: SHOP_TZ });
for (let day = 0; day <= 14; day++) {
  const d = startDay.plus({ days: day });
  if (d > endLimit) break;
  if (d.weekday === 6 || d.weekday === 7) continue;
  for (let m = workStart * 60; m + slotDuration <= workEnd * 60; m += stepMin) {
    const hour = Math.floor(m / 60), minute = m % 60;
    const sDT = d.set({ hour, minute, second: 0, millisecond: 0 });
    const s = sDT.toJSDate();
    const e = new Date(s.getTime() + slotDuration * 60000);
    if (s < nowJs || s < dateRangeStart || e > dateRangeEnd) continue;
    if (isSlotAvailable(s, e)) {
      availableSlots.push({ start: s.toISOString(), end: e.toISOString(), formatted: sDT.toFormat("cccc, LLLL d 'at' h:mm a"), distance: Math.abs(s.getTime() - requestedStartTime.getTime()) });
    }
  }
}
availableSlots.sort((a, b) => a.distance - b.distance);
const closestSlots = availableSlots.slice(0, 3).map(({ distance, ...rest }) => rest);
return [{ json: { requestedTime: requestedStartTime.toISOString(), alternativeSlots: closestSlots, totalAvailableSlots: availableSlots.length } }];

const items = $input.all().filter(i => i.json && i.json.id && i.json.sourceCalendarId);
