if (wantBarber) matches = matches.filter(ev => barberOf(ev).toLowerCase() === wantBarber);
if (wantDate) matches = matches.filter(ev => dateOf(ev) === wantDate);
if (matches.length === 1) { const ev = matches[0]; return [{ json: { status: 'found', eventId: ev.id, calendarId: calOf(ev), barber: barberOf(ev) } }]; }
