const options = matches.map(ev => ({ barber: barberOf(ev), date: dateOf(ev), time: (ev.start && (ev.start.dateTime || ev.start.date)) || '', eventId: ev.id, calendarId: calOf(ev), summary: ev.summary || '' }));
return [{ json: { status: 'ambiguous', options } }];

