const SHOP_TZ = $now.zoneName;
const barbers = [];
const configuredCalendarIds = [];
const configuredCalendarSet = new Set();
for (const item of $('Access All Barber Data').all()) {
  const row = item.json || {};
  const barber = String(row.barber ?? '').trim();
  const calendarId = String(row.calendarId ?? '').trim();
  if (!barber || !calendarId || configuredCalendarSet.has(calendarId)) continue;
  configuredCalendarSet.add(calendarId);
  configuredCalendarIds.push(calendarId);
  barbers.push({ barber, calendarId });
}
const body = $('Book Appointment Webhook').first().json.body;
const reqStart = new Date(body.startTime);
const reqEnd = new Date(body.endTime);
const durationMs = (reqEnd - reqStart) > 0 ? (reqEnd - reqStart) : 60 * 60000;
const durationMin = durationMs / 60000;
const phoneKey = String(body.number || body.phone_number || '').replace(/\D/g, '').slice(-10);
const workStart = 9, workEnd = 17, stepMin = 30, rangeDays = 10;
const nowJs = new Date();
const busyByCal = {};
const failedCalendars = new Set();
const successfulCalendars = new Set();
const seenBusyEventKeysByCalendar = new Map();
for (const it of $input.all()) {
  const ev = it.json || {};
  const cal = String(ev.sourceCalendarId || '').trim();
  if (!configuredCalendarSet.has(cal)) continue;
  if (Object.prototype.hasOwnProperty.call(ev, 'error') && ev.error) {
    failedCalendars.add(cal);
    continue;
  }
  successfulCalendars.add(cal);
  if (String(ev.status || '').toLowerCase() === 'cancelled') continue;
  if (String(ev.transparency || '').toLowerCase() === 'transparent') continue;
  if (Array.isArray(ev.attendees) && ev.attendees.some(a => a && a.self === true && String(a.responseStatus || '').toLowerCase() === 'declined')) continue;
  if (!ev.start) continue;
  const s = new Date(ev.start.dateTime || ev.start.date);
  const e = new Date((ev.end && (ev.end.dateTime || ev.end.date)) || s);
  if (Number.isNaN(s.getTime()) || Number.isNaN(e.getTime())) continue;
  const eventId = String(ev.id ?? '').trim();
  const eventKey = eventId
    ? `id:${eventId}`
    : `time:${s.toISOString()}|${e.toISOString()}|${String(ev.summary ?? '')}|${String(ev.status ?? '')}`;
  let seenBusyEventKeys = seenBusyEventKeysByCalendar.get(cal);
  if (!seenBusyEventKeys) {
    seenBusyEventKeys = new Set();
    seenBusyEventKeysByCalendar.set(cal, seenBusyEventKeys);
  }
  if (seenBusyEventKeys.has(eventKey)) continue;
  seenBusyEventKeys.add(eventKey);
  (busyByCal[cal] = busyByCal[cal] || []).push({ start: s, end: e });
}
const readableCalendars = new Set(configuredCalendarIds.filter(cal => successfulCalendars.has(cal) && !failedCalendars.has(cal)));
const failedConfiguredCalendars = configuredCalendarIds.filter(cal => !readableCalendars.has(cal));
