const freeNow = eligibleBarbers.filter(b => isFree(b.calendarId, reqStart, reqEnd));
if (freeNow.length) {
  const reqDT = DateTime.fromISO(body.startTime, { zone: SHOP_TZ });
  const dayStart = reqDT.startOf('day').toJSDate();
  const dayEnd = reqDT.startOf('day').plus({ days: 1 }).toJSDate();
  const dayLoad = calId => busyBlocks(calId).filter(b => b.start < dayEnd && b.end > dayStart).length;
  freeNow.sort((a, b) => dayLoad(a.calendarId) - dayLoad(b.calendarId));
  const chosen = freeNow[0];
  return [{ json: { assigned: true, calendarReadStatus, barber: chosen.barber, calendarId: chosen.calendarId, phoneKey, startTime: body.startTime, endTime: body.endTime } }];
}
const suggestions = [];
const dayCursor = DateTime.fromISO(body.startTime, { zone: SHOP_TZ }).startOf('day');
for (let day = 0; day < rangeDays; day++) {
  const d = dayCursor.plus({ days: day });
  if (d.weekday === 6 || d.weekday === 7) continue;
  for (let m = workStart * 60; m + durationMin <= workEnd * 60; m += stepMin) {
    const hour = Math.floor(m / 60), minute = m % 60;
    const sDT = d.set({ hour, minute, second: 0, millisecond: 0 });
    const s = sDT.toJSDate();
    const e = new Date(s.getTime() + durationMs);
    if (s < nowJs) continue;
    for (const b of eligibleBarbers) {
      if (isFree(b.calendarId, s, e)) {
        suggestions.push({ startTime: s.toISOString(), endTime: e.toISOString(), barber: b.barber, formatted: sDT.toFormat("cccc, LLLL d 'at' h:mm a"), dist: Math.abs(s - reqStart) });
        break;
      }
    }
  }
}
suggestions.sort((a, b) => a.dist - b.dist);
const top3 = suggestions.slice(0, 3).map(({ dist, ...rest }) => rest);
return [{ json: { assigned: false, calendarReadStatus, phoneKey, suggestedTimes: top3, message: top3.length ? 'No barber is available at that time. Here are the closest openings.' : 'No availability found in the requested range.' } }];

